import { _decorator, AudioSource, Button, Component, director, Node, Slider } from 'cc';
import { mEmitter } from '../mEmitter';
import { CharacterEventType, MoveDirection, animations, GameStateType } from '../constants';
import { GameState } from '../gameState';
import { onButtonClick } from '../button/handler';
import { AudioManager } from '../audioManager';
import { PopupManager } from './popupManager';

const { ccclass, property } = _decorator;

@ccclass('SettingPopup')
export class SettingPopup extends Component {

    @property(Button)
    sfxButton: Button;

    @property(Slider)
    sfxSlider: Slider;

    @property(Button)
    bgmButton: Button;

    @property(Slider)
    bgmSlider: Slider;

    protected onLoad(): void {
    }

    protected start(): void {
        this.initMusicButton();
    }

    initMusicButton() {
        if (AudioManager.instance.bgmMute) {
            onButtonClick(this.bgmButton);
        }
        if (AudioManager.instance.sfxMute){
            onButtonClick(this.sfxButton);
        }
    }

    showPopup() {

    }

    pauseGame() {
        mEmitter.instance.emit(GameStateType.TOGGLEPAUSE);
    }

    onClickHoli() {
        console.log(this.bgmButton)
        onButtonClick(this.bgmButton);
        // let temp = GameState.instance.popupNode;
        // if (temp) {
        //     temp.active = !temp.active;
        // }

    }

    setVolumn(value: number) {
        AudioManager.instance.setBGMVolume(this.sfxSlider.progress)
        AudioManager.instance.setSFXVolume(this.bgmSlider.progress);
    }

    toggleSFX() {
        onButtonClick(this.sfxButton);
        AudioManager.instance.toggleSFX();
        this.playSFX();
    }

    toggleBGM() {
        onButtonClick(this.bgmButton);
        AudioManager.instance.toggleBGM();
    }

    togglePopup() {
        PopupManager.instance.hidePopup();
    }

    playSFX() {
        AudioManager.instance.playSFX();
    }
}

